def count_words(text: str) -> int:
    """
    Count the number of words in a text string.
    
    Args:
        text: Input text.
    
    Returns:
        int: Word count.
    """
    return len(text.split())


def extract_citations(text: str) -> List[str]:
    """
    Extract all citation markers from text.
    
    Args:
        text: Input text.
    
    Returns:
        List[str]: List of citation markers.
    """
    return CITATION_PATTERN.findall(text)


def validate_timeline_format(timeline_text: str) -> Tuple[bool, Optional[str]]:
    """
    Validate the timeline section format.
    
    Args:
        timeline_text: Content of the timeline section.
    
    Returns:
        Tuple[bool, Optional[str]]: (is_valid, error_message)
    """
    # Check for month/year patterns
    month_pattern = re.compile(
        r'(?:Month|Q[1-4]|Phase)\s+\d+|'
        r'(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+\d{4}',
        re.IGNORECASE
    )
    
    if not month_pattern.search(timeline_text):
        return False, "Timeline does not contain recognizable time markers"
    
    # Check for duration estimates
    duration_pattern = re.compile(r'\d+\s*(?:month|week|day|year)s?', re.IGNORECASE)
    if not duration_pattern.search(timeline_text):
        return False, "Timeline does not contain duration estimates"
    
    return True, None


def validate_risk_entry(risk_text: str) -> Tuple[bool, Optional[str]]:
    """
    Validate a risk entry format.
    
    Args:
        risk_text: Content of a risk entry.
    
    Returns:
        Tuple[bool, Optional[str]]: (is_valid, error_message)
    """
    # Check for severity level
    severity_pattern = re.compile(
        r'(?:Severity|Risk Level|Impact)\s*:\s*(' + '|'.join(RISK_SEVERITY_LEVELS) + r')',
        re.IGNORECASE
    )
    
    if not severity_pattern.search(risk_text):
        return False, "Risk entry missing severity level"
    
    # Check for mitigation strategy
    mitigation_pattern = re.compile(
        r'(?:Mitigation|Mitigate|Prevent|Avoid|Reduce)\s*:',
        re.IGNORECASE
    )
    
    if not mitigation_pattern.search(risk_text):
        return False, "Risk entry missing mitigation strategy"
    
    return True, None


