    def test_required_sections_present(self, parsed_sections: Dict[str, str]):
        """Verify all required sections are present in the document."""
        missing_sections = [
            section for section in REQUIRED_SECTIONS
            if not any(section.lower() in key.lower() for key in parsed_sections.keys())
        ]
        assert not missing_sections, f"Missing required sections: {missing_sections}"
        logger.info(f"All {len(REQUIRED_SECTIONS)} required sections present")
    
    def test_section_order(self, parsed_sections: Dict[str, str]):
        """Verify sections appear in the expected logical order."""
        section_keys = list(parsed_sections.keys())
        expected_order = [s.lower() for s in REQUIRED_SECTIONS]
        
        # Check that required sections appear in order
        last_index = -1
        for expected_section in expected_order:
            found = False
            for i, key in enumerate(section_keys):
                if expected_section in key.lower():
                    if i <= last_index:
                        pytest.fail(f"Section '{key}' appears out of order")
                    last_index = i
                    found = True
                    break
            if not found:
                logger.warning(f"Section '{expected_section}' not found in parsed sections")
    
    def test_no_empty_sections(self, parsed_sections: Dict[str, str]):
        """Verify no sections are empty."""
