class TestResearchPlanEdgeCases:
    """Test suite for edge case handling."""
    
    def test_special_characters(self, research_plan_content: Optional[str]):
        """Verify document handles special characters properly."""
        if research_plan_content is None:
            pytest.skip("Research plan content not available")
        
        # Check for unicode characters
        unicode_chars = re.findall(r'[^\x00-\x7F]', research_plan_content)
        if unicode_chars:
            logger.info(f"Document contains {len(unicode_chars)} unicode characters")
    
    def test_markdown_formatting(self, research_plan_content: Optional[str]):
        """Verify markdown formatting is consistent."""
        if research_plan_content is None:
            pytest.skip("Research plan content not available")
        
        # Check for unclosed formatting
        formatting_pairs = [
            (r'\*\*', r'\*\*'),  # Bold
            (r'\*', r'\*'),      # Italic
            (r'`', r'`'),        # Code
            (r'\$\$', r'\$\$'),  # Display math
            (r'\$', r'\$'),      # Inline math
        ]
        
        for open_pattern, close_pattern in formatting_pairs:
            opens = len(re.findall(open_pattern, research_plan_content))
            closes = len(re.findall(close_pattern, research_plan_content))
            
            if opens != closes:
                logger.warning(f"Unmatched formatting: {open_pattern} ({opens} opens, {closes} closes)")
    
    def test_url_validity(self, research_plan_content: Optional[str]):
        """Verify URLs in document are well-formed."""
        if research_plan_content is None:
            pytest.skip("Research plan content not available")
        
        url_pattern = re.compile(
            r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+'
            r'(?:/[-\w$.+!*\'(),;:@&=?/~#%]*)?'
        )
        
        urls = url_pattern.findall(research_plan_content)
        invalid_urls = []
        
        for url in urls:
            # Basic URL validation
            if not url.startswith(('http://', 'https://')):
                invalid_urls.append(url)
            elif '..' in url:
                invalid_urls.append(url)
        
        assert not invalid_urls, f"Invalid URLs found: {invalid_urls}"


